function installActivityNotificationListener() {
  const localNotifications = getLocalNotifications();
  if (activityNotificationListenerInstalled || !localNotifications
      || typeof localNotifications.addListener !== 'function') return;

  try {
    localNotifications.addListener('localNotificationActionPerformed', async (event) => {
      const notification = event && event.notification;
      if (!notification) return;
      const extra = notification.extra || {};
      if (extra.source === 'fitflow-water-reminder') {
        addWater(250);
        toast('💧 +250 мл воды по напоминанию');
        return;
      }
      if (extra.source === 'fitflow-training-reminder') {
        await removeDeliveredTrainingReminder(localNotifications, notification.id);
        switchView('training');
        toast('Была сегодня активность? Выберите вид и добавьте запись.');
        return;
      }
      if (extra.source === 'fitflow-meal-reminder') {
        switchView('home');
        selectedMealTypeId = extra.mealId || '';
        mealTypeTouched = !!selectedMealTypeId;
        renderMealTypePicker();
        setTimeout(() => $('#food-input').focus(), 250);
        toast(`Запишите ${extra.mealLabel || 'приём пищи'} в дневник`);
        return;
      }
      if (notification.id >= MORNING_MOTIVATION_NOTIFICATION_BASE_ID
          && notification.id < MORNING_MOTIVATION_NOTIFICATION_BASE_ID + MORNING_MOTIVATION_SCHEDULE_DAYS) {
        const extra = notification.extra || {};
        showMorningMessageDialog(extra.message || notification.largeBody || notification.body);
      }
    });
    activityNotificationListenerInstalled = true;
  } catch (e) {
    console.warn('Не удалось подключить обработчик вечернего вопроса:', e);
  }
}

async function ensureMealReminderChannel(localNotifications) {
  if (typeof localNotifications.createChannel !== 'function') return;
  await localNotifications.createChannel({
    id: MEAL_REMINDER_CHANNEL,
    name: 'FitFlow: приёмы пищи',
    description: 'Напоминания записать завтрак, обед и другие приёмы пищи',
    importance: 4,
    visibility: 1,
    sound: 'default',
    vibrates: true
  });
}

function mealNotificationId(mealId, dateKey) {
  const text = `${mealId}|${dateKey}`;
  let hash = 2166136261;
  for (let i = 0; i < text.length; i++) { hash ^= text.charCodeAt(i); hash = Math.imul(hash, 16777619); }
  return 900000000 + ((hash >>> 0) % 900000000);
}

function mealReminderNotificationIds() {
  const legacy = Array.from({ length: MEAL_REMINDER_TYPES.length * MEAL_REMINDER_SCHEDULE_DAYS }, (_, index) => MEAL_REMINDER_NOTIFICATION_BASE_ID + index);
  const ids = [];
  const base = new Date();
  base.setHours(0, 0, 0, 0);
  for (let offset = 0; offset <= MEAL_REMINDER_SCHEDULE_DAYS; offset++) {
    const day = new Date(base.getTime());
    day.setDate(day.getDate() + offset);
    const pad = (value) => String(value).padStart(2, '0');
    const date = `${day.getFullYear()}-${pad(day.getMonth() + 1)}-${pad(day.getDate())}`;
    getMealTypes().forEach((meal) => ids.push(mealNotificationId(meal.id, date)));
  }
  return [...legacy, ...ids];
}

function hasMealTypeOnDate(mealId, date = todayKey()) {
  return state.food.items.some((item) => item.mealTypeId === mealId && state.food.date === date);
}

async function cancelMealReminders(localNotifications = getLocalNotifications()) {
  if (!localNotifications) return;
  try { await localNotifications.cancel({ notifications: mealReminderNotificationIds().map((id) => ({ id })) }); } catch (e) { }
}

async function scheduleMealReminders({ requestPermission = true } = {}) {
  const localNotifications = getLocalNotifications();
  if (!localNotifications) return { ok: false, message: 'Напоминания о питании работают только в Android-приложении.' };
  let allowed = false;
  if (requestPermission) allowed = await ensureNotificationPermission(localNotifications);
  else { try { allowed = (await localNotifications.checkPermissions()).display === 'granted'; } catch (e) { } }
  if (!allowed) return { ok: false, message: 'Разрешите уведомления Android, чтобы включить напоминания о питании.' };
  try {
    await ensureMealReminderChannel(localNotifications);
    await cancelMealReminders(localNotifications);
    const notifications = [];
    state.mealReminders.meals.filter((meal) => meal.enabled).forEach((meal) => {
      const firstAt = nextReminderDate(meal.time);
      for (let dayIndex = 0; dayIndex < MEAL_REMINDER_SCHEDULE_DAYS; dayIndex++) {
        const at = new Date(firstAt.getTime());
        at.setDate(at.getDate() + dayIndex);
        const pad = (value) => String(value).padStart(2, '0');
        const date = `${at.getFullYear()}-${pad(at.getMonth() + 1)}-${pad(at.getDate())}`;
        if (hasMealTypeOnDate(meal.id, date)) continue;
        notifications.push({
          id: mealNotificationId(meal.id, date),
          title: `Пора записать: ${meal.label} · ${meal.time}`,
          body: `Не забудьте добавить ваш ${meal.label.toLowerCase()} в FitFlow.`,
          schedule: { at, allowWhileIdle: true },
          channelId: MEAL_REMINDER_CHANNEL,
          smallIcon: 'ic_stat_icon', iconColor: '#FF9E3D', autoCancel: true,
          extra: { source: 'fitflow-meal-reminder', mealId: meal.id, mealLabel: meal.label }
        });
      }
    });
    if (notifications.length) await localNotifications.schedule({ notifications });
    return { ok: true };
  } catch (e) {
    console.warn('Не удалось запланировать напоминания о питании:', e);
    return { ok: false, message: 'Не удалось включить напоминания о питании. Проверьте разрешения Android.' };
  }
}


/* ==== ВОДНЫЕ НАПОМИНАНИЯ ==== */

async function ensureWaterReminderChannel(localNotifications) {
  if (typeof localNotifications.createChannel !== 'function') return;
  await localNotifications.createChannel({
    id: WATER_REMINDER_CHANNEL,
    name: 'FitFlow: вода',
    description: 'Регулярные напоминания выпить воду',
    importance: 3,
    visibility: 1,
    sound: 'default',
    vibrates: false
  });
}

function waterReminderIds() {
  const ids = [];
  for (let d = 0; d <= WATER_REMINDER_SCHEDULE_DAYS; d++) {
    for (let slot = 0; slot < 25; slot++) {
      ids.push(75000 + d * 100 + slot);
    }
  }
  return ids;
}

/* Минуты от полуночи для всех напоминаний в окне [start; end] с шагом interval.
   Окно через полночь (например, 22:00–02:00) тоже поддерживается.
   Результат отсортирован и без дублей. */
function buildWaterReminderTimes(interval, windowStart, windowEnd) {
  const toMin = (s) => {
    const parts = String(s || '').split(':');
    const h = Number(parts[0]);
    const m = Number(parts[1]);
    if (!Number.isFinite(h) || !Number.isFinite(m) || h < 0 || h > 23 || m < 0 || m > 59) return null;
    return h * 60 + m;
  };
  const step = Math.max(1, Number(interval) || 90);
  const start = toMin(windowStart);
  let end = toMin(windowEnd);
  if (start === null || end === null) return [];
  if (end < start) end += 24 * 60; // окно через полночь
  const times = [];
  for (let t = start; t <= end; t += step) times.push(t % (24 * 60));
  return [...new Set(times)].sort((a, b) => a - b);
}

function getNativeBridge() {
  return (typeof window !== 'undefined' && window.FitFlowExport) ? window.FitFlowExport : null;
}

async function cancelWaterReminders(localNotifications = getLocalNotifications()) {
  const bridge = getNativeBridge();
  if (bridge && typeof bridge.cancelWaterRemindersNative === 'function') {
    try { bridge.cancelWaterRemindersNative(); } catch (e) { }
  }
  if (!localNotifications) return;
  try { await localNotifications.cancel({ notifications: waterReminderIds().map((id) => ({ id })) }); } catch (e) { }
}

async function scheduleWaterReminders({ requestPermission = true } = {}) {
  const localNotifications = getLocalNotifications();
  const bridge = getNativeBridge();
  const hasNative = bridge && typeof bridge.scheduleWaterRemindersNative === 'function';
  if (!localNotifications && !hasNative) return { ok: false, message: 'Напоминания о воде работают только в Android-приложении.' };
  let allowed = false;
  if (localNotifications) {
    if (requestPermission) allowed = await ensureNotificationPermission(localNotifications);
    else { try { allowed = (await localNotifications.checkPermissions()).display === 'granted'; } catch (e) { } }
  } else {
    try { allowed = bridge.areNotificationsEnabled(); } catch (e) { allowed = false; }
  }
  if (!allowed) return { ok: false, message: 'Разрешите уведомления для напоминаний о воде.' };

  /* Приоритет — нативный планировщик: уведомление с кнопкой «+250 мл»
     работает прямо из шторки, без открытия приложения, и обновляет виджет.
     JS-напоминания остаются запасным вариантом для старых сборок. */
  if (hasNative) {
    try {
      const wr = state.waterReminders;
      const times = buildWaterReminderTimes(wr.interval, wr.windowStart, wr.windowEnd);
      if (times.length === 0) return { ok: false, message: 'Проверьте окно напоминаний о воде.' };
      bridge.scheduleWaterRemindersNative(times.join(','));
      // Снять возможные старые JS-уведомления, чтобы не было дублей.
      if (localNotifications) try { await localNotifications.cancel({ notifications: waterReminderIds().map((id) => ({ id })) }); } catch (e) { }
      return { ok: true, count: times.length, native: true };
    } catch (e) {
      console.warn('Нативный планировщик воды недоступен, переключаюсь на JS:', e);
    }
  }
  if (!localNotifications) return { ok: false, message: 'Напоминания о воде сейчас недоступны.' };
  try {
    await ensureWaterReminderChannel(localNotifications);
    await cancelWaterReminders(localNotifications);
    const wr = state.waterReminders;
    const [sh, sm] = wr.windowStart.split(':').map(Number);
    const [eh, em] = wr.windowEnd.split(':').map(Number);
    const now = new Date();
    const notifications = [];
    let slotCounter = 0;
    for (let d = 0; d <= WATER_REMINDER_SCHEDULE_DAYS; d++) {
      const base = new Date(); base.setDate(base.getDate() + d);
      let at = new Date(base); at.setHours(sh, sm, 0, 0);
      const dayEnd = new Date(base); dayEnd.setHours(eh, em, 0, 0);
      while (at <= dayEnd && slotCounter < 75) {
        if (at > now) {
          notifications.push({
            id: 75000 + d * 100 + slotCounter,
            title: '💧 Время выпить воду',
            body: `Не забудьте добавить воду в FitFlow. Сейчас: ${state.water.total || 0} из ${state.water.goal} мл.`,
            schedule: { at: new Date(at), allowWhileIdle: true },
            channelId: WATER_REMINDER_CHANNEL,
            smallIcon: 'ic_stat_icon', iconColor: '#00696B', autoCancel: true,
            extra: { source: 'fitflow-water-reminder' }
          });
        }
        at = new Date(at.getTime() + wr.interval * 60000);
        slotCounter++;
      }
    }
    if (notifications.length) await localNotifications.schedule({ notifications });
    return { ok: true, count: notifications.length };
  } catch (e) {
    console.warn('Не удалось запланировать напоминания о воде:', e);
    return { ok: false, message: 'Не удалось включить напоминания о воде.' };
  }
}

async function refreshWaterRemindersOnLaunch() {
  if (!state.waterReminders.enabled || !getLocalNotifications()) return;
  await scheduleWaterReminders({ requestPermission: false });
}

function renderWaterReminderSettings() {
  if (typeof document === 'undefined') return;
  const toggle = $('#water-reminders-toggle');
  const status = $('#water-reminders-status');
  const opts = $('#water-reminders-options');
  if (!toggle || !status) return;
  toggle.checked = state.waterReminders.enabled;
  if (opts) opts.hidden = !state.waterReminders.enabled;
  $$('#water-interval-choices button').forEach((btn) =>
    btn.classList.toggle('active', Number(btn.dataset.waterInterval) === state.waterReminders.interval));
  status.textContent = state.waterReminders.enabled
    ? `Каждые ${state.waterReminders.interval} мин с ${state.waterReminders.windowStart} до ${state.waterReminders.windowEnd}.`
    : 'Напоминания о воде выключены.';
}

async function updateWaterRemindersEnabled(enabled) {
  state.waterReminders.enabled = enabled;
  saveState();
  renderWaterReminderSettings();
  if (!enabled) { await cancelWaterReminders(); toast('Напоминания о воде выключены'); return; }
  const result = await scheduleWaterReminders();
  if (!result.ok) { state.waterReminders.enabled = false; saveState(); renderWaterReminderSettings(); toast(result.message); return; }
  toast(`Напоминания о воде включены: каждые ${state.waterReminders.interval} мин`);
}

async function updateWaterReminderInterval(interval) {
  state.waterReminders.interval = interval;
  saveState();
  renderWaterReminderSettings();
  if (!state.waterReminders.enabled) return;
  await scheduleWaterReminders();
  toast(`Интервал: каждые ${interval} мин`);
}

